const fs = await import("node:fs");
const dir = "/work/workspace/deliverable";
const files = fs.readdirSync(dir);
const out = { files };

// 1) JSON parse
try {
  const j = JSON.parse(fs.readFileSync(dir + "/classificacoes.json", "utf8"));
  out.json_ok = true;
  out.json_keys = Object.keys(j);
} catch (e) { out.json_ok = false; out.json_err = String(e); }

// 2) citations referenced in deliverables
const cite = new Set();
for (const f of files.filter(f => f.endsWith(".md"))) {
  const t = fs.readFileSync(dir + "/" + f, "utf8");
  for (const m of t.matchAll(/library\/[a-z0-9_\-\.]+\.md/g)) cite.add(m[0]);
}
out.cited = [...cite].sort();

// library actual files per INDEX
const index = fs.readFileSync("/work/workspace/library/INDEX.md", "utf8");
const libFiles = [...index.matchAll(/[a-zA-Z0-9_\-]+\.md/g)].map(x => "library/" + x[0]);
out.libFiles = [...new Set(libFiles)].sort();
out.all_citations_in_library = out.cited.every(c => out.libFiles.includes(c));

// 3) latin-1 / mojibake / cyrillic sweep
let bad = [];
for (const f of files) {
  const t = fs.readFileSync(dir + "/" + f, "utf8");
  for (const ch of t) {
    const cp = ch.codePointAt(0);
    if ((cp >= 0x0400 && cp <= 0x04FF) || (cp >= 0x80 && cp <= 0x9F)) { bad.push(f + ": U+" + cp.toString(16) + " " + ch); }
  }
}
out.badChars = bad;
return out;

